            RemoveOccurrenceDefinition(SysmlLanguage.Instance.IOccurrenceUsage_occurrenceDefinition.AsNodes<LionWeb.Demo.SysMl2.Languages.SysMl2.IClass>(value));
            return true;
        }

        if (SysmlLanguage.Instance.IPartUsage_partDefinition.EqualsIdentity(link))
        {
            RemovePartDefinition(SysmlLanguage.Instance.IPartUsage_partDefinition.AsNodes<LionWeb.Demo.SysMl2.Languages.SysMl2.PartDefinition>(value));
            return true;
        }

        return false;
    }
